[ExtensionOf(tableStr(ReqItemCoverageSettingsV2Entity))]
final  class METReqItemCoverageSettingsV2Entity_Extension
{   
}

Method.Source:
/// <summary>
/// Validates the record buffer before writing
/// </summary>
/// <returns>True if the record is valid. Otherwise false</returns>
public boolean validateWrite()
{
    boolean ret;
    ret = next validateWrite();
    
    if (this.PlannedOrderType == reqpotype::transfer && this.METAlternateSellUnitWH == '')
    {            
        ret = checkFailed("@MET:AlternateSellUnitMandatory");
    }
    
    return ret;        
}

    /// <summary>
    /// VM - CB264 - Pickupslot
    /// Maps the field based on the value in reference table
    /// </summary>
    /// <param name = "_entityCtx">The context of the entity.</param>
    /// <param name = "_dataSourceCtx">The context of the datasource being mapped.</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        MetOrderSplitCategoryArea   metOrderSplitCategoryArea;

        //Check if desired data source METReqItemTable is available
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(ReqItemCoverageSettingsV2Entity, METReqItemTable))
        {
            //// If record exist then update the oscc code
            select firstonly CategoryArea from metOrderSplitCategoryArea
                where metOrderSplitCategoryArea.Area == this.METArea
                && metOrderSplitCategoryArea.OSCC == this.METOSCCode;

            if (metOrderSplitCategoryArea)
            {
                this.METOSCCode = metOrderSplitCategoryArea.CategoryArea;
            }
        }

        next mapEntityToDataSource(_entityCtx,  _dataSourceCtx);

    }

    /// <summary>
    /// During inserting record
    /// </summary>    
    public void insert()
    {
        /// CB269 Item MDR
        /// Clear field "Alternate sell unit warehouse" for type "Purchase"
        if (this.PlannedOrderType == ReqPOType::Purch)
        {
            this.METAlternateSellUnitWH = '';
        }

        next insert();
    }

/// <summary>
/// During updating record
/// </summary>    
public void update()
{
    /// CB269 Item MDR
    /// Clear field "Alternate sell unit warehouse" for type "Purchase"
    if (this.PlannedOrderType == ReqPOType::Purch)
    {
        this.METAlternateSellUnitWH = '';
    }
    
    next update();
}
